using System.Security.Cryptography;
using System.Text;

namespace PostgreManagementStudio.Application;

public sealed record IndexKeyDefinition(string Expression, bool Descending = false, bool NullsFirst = false, string? OperatorClass = null, string? Collation = null);
public sealed record IndexMetadata(uint IndexOid, uint TableOid, string SchemaName, string TableName, string IndexName, string AccessMethod, IReadOnlyList<IndexKeyDefinition> Keys, IReadOnlyList<string> IncludedColumns, string? Predicate = null, bool IsUnique = false, bool IsPrimary = false, bool IsValid = true, bool IsReady = true, bool IsLive = true, long SizeBytes = 0, long ScanCount = 0, bool IsConstraintBacked = false, bool IsReplicaIdentity = false);
public sealed record ForeignKeyMetadata(string SchemaName, string TableName, string ConstraintName, IReadOnlyList<string> ReferencingColumns, string ReferencedTable, IReadOnlyList<string> ReferencedColumns);
public enum IndexRecommendationCategory { Invalid, Duplicate, Overlap, Unused, MissingForeignKey, MissingIndex, Health }
public enum RecommendationSeverity { Information, Notice, Warning, High }
public enum RecommendationConfidence { Low, Moderate, High }
public enum IndexRiskLevel { Low, Moderate, High, Destructive, Blocked }
public sealed record RecommendationEvidence(string Evidence, string Limitation);
public sealed record IndexRecommendation(string RecommendationId, IndexRecommendationCategory Category, RecommendationSeverity Severity, RecommendationConfidence Confidence, IndexRiskLevel Risk, string Summary, IReadOnlyList<RecommendationEvidence> Evidence, string? ProposedSql, IReadOnlyList<string> Limitations, IReadOnlyList<IndexMetadata> Objects);
public sealed record IndexAnalysisSnapshot(DateTimeOffset CapturedAt, DateTimeOffset? StatisticsResetAt, IReadOnlyList<IndexMetadata> Indexes, IReadOnlyList<ForeignKeyMetadata> ForeignKeys);

public static class IndexAnalysisService
{
    public static string Fingerprint(IndexMetadata index)
    { var value = string.Join("|", index.TableOid, index.AccessMethod.ToLowerInvariant(), index.IsUnique, string.Join(",", index.Keys.Select(k => string.Join(":", Normalize(k.Expression), k.Descending, k.NullsFirst, k.OperatorClass, k.Collation))), string.Join(",", index.IncludedColumns.Select(Normalize)), Normalize(index.Predicate ?? "")); return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value))).ToLowerInvariant(); }
    public static IReadOnlyList<IReadOnlyList<IndexMetadata>> FindDuplicates(IEnumerable<IndexMetadata> indexes) => indexes.GroupBy(Fingerprint).Where(x => x.Count() > 1).OrderBy(x => x.Key, StringComparer.Ordinal).Select(x => (IReadOnlyList<IndexMetadata>)x.OrderBy(i => i.IndexName, StringComparer.Ordinal).ToArray()).ToArray();
    public static IReadOnlyList<(IndexMetadata Smaller, IndexMetadata Larger)> FindOverlaps(IEnumerable<IndexMetadata> indexes)
    { var result = new List<(IndexMetadata, IndexMetadata)>(); foreach (var group in indexes.Where(x => x.Keys.Count > 0 && string.IsNullOrEmpty(x.Predicate) && x.AccessMethod.Equals("btree", StringComparison.OrdinalIgnoreCase)).GroupBy(x => new { x.TableOid, x.AccessMethod })) { var ordered = group.OrderBy(x => x.Keys.Count).ThenBy(x => x.IndexName, StringComparer.Ordinal).ToArray(); for (var i = 0; i < ordered.Length; i++) for (var j = i + 1; j < ordered.Length; j++) if (PrefixEqual(ordered[i], ordered[j])) result.Add((ordered[i], ordered[j])); } return result; }
    public static IReadOnlyList<IndexRecommendation> Recommend(IEnumerable<IndexMetadata> indexes, IEnumerable<ForeignKeyMetadata> foreignKeys, TimeSpan? observationWindow = null)
    { var all = indexes.ToArray(); var result = new List<IndexRecommendation>(); foreach (var index in all.Where(x => !x.IsValid || !x.IsReady || !x.IsLive)) result.Add(new($"invalid:{index.IndexOid}", IndexRecommendationCategory.Invalid, RecommendationSeverity.High, RecommendationConfidence.High, IndexRiskLevel.Blocked, $"Index {Qualified(index)} is not valid or ready.", new[] { new RecommendationEvidence($"valid={index.IsValid}, ready={index.IsReady}, live={index.IsLive}", "The catalogue state does not identify the original failure cause.") }, null, new[] { "Investigate before using or rebuilding this index." }, new[] { index })); foreach (var group in FindDuplicates(all)) { var retain = group.OrderByDescending(x => x.IsPrimary || x.IsConstraintBacked).ThenByDescending(x => x.IsReplicaIdentity).ThenByDescending(x => x.IsValid && x.IsReady).ThenByDescending(x => x.ScanCount).ThenBy(x => x.IndexName, StringComparer.Ordinal).First(); foreach (var duplicate in group.Where(x => x != retain)) { var protectedIndex = duplicate.IsPrimary || duplicate.IsConstraintBacked || duplicate.IsReplicaIdentity; result.Add(new($"duplicate:{Fingerprint(duplicate)}:{duplicate.IndexName}", IndexRecommendationCategory.Duplicate, RecommendationSeverity.Warning, RecommendationConfidence.High, protectedIndex ? IndexRiskLevel.Blocked : IndexRiskLevel.Destructive, $"Index {Qualified(duplicate)} is semantically duplicated by {Qualified(retain)}.", new[] { new RecommendationEvidence("All semantic key, predicate, include, and access-method properties match.", "A duplicate may still be retained for operational or deployment reasons.") }, protectedIndex ? null : $"DROP INDEX {PostgreSqlIdentifierQuoter.Qualified(duplicate.SchemaName, duplicate.IndexName)};", new[] { "Review usage, constraints, replicas, and deployment dependencies before removal." }, new[] { duplicate, retain })); } } foreach (var fk in foreignKeys) if (!all.Any(i => i.TableName == fk.TableName && i.SchemaName == fk.SchemaName && i.IsValid && i.IsReady && i.Keys.Select(k => k.Expression).Take(fk.ReferencingColumns.Count).SequenceEqual(fk.ReferencingColumns, StringComparer.OrdinalIgnoreCase))) { var name = $"ix_{fk.TableName}_{string.Join("_", fk.ReferencingColumns)}"; result.Add(new($"fk:{fk.SchemaName}.{fk.TableName}.{fk.ConstraintName}", IndexRecommendationCategory.MissingForeignKey, RecommendationSeverity.Notice, RecommendationConfidence.Moderate, IndexRiskLevel.Low, $"Foreign key {fk.SchemaName}.{fk.ConstraintName} has no matching leading-key index.", new[] { new RecommendationEvidence($"Referencing columns: ({string.Join(", ", fk.ReferencingColumns)})", "PostgreSQL does not require a referencing-column index; it can benefit parent updates, deletes, and joins.") }, $"CREATE INDEX CONCURRENTLY {PostgreSqlIdentifierQuoter.Quote(name)} ON {PostgreSqlIdentifierQuoter.Qualified(fk.SchemaName, fk.TableName)} ({string.Join(", ", fk.ReferencingColumns.Select(PostgreSqlIdentifierQuoter.Quote))});", new[] { "Validate workload selectivity and existing indexes before creation." }, Array.Empty<IndexMetadata>())); } return result.OrderByDescending(x => x.Severity).ThenByDescending(x => x.Confidence).ThenBy(x => x.RecommendationId, StringComparer.Ordinal).ToArray(); }
    public static string GenerateReviewScript(IEnumerable<IndexRecommendation> recommendations) { var b = new StringBuilder("-- PostgreManagementStudio Index Analysis Review Script\n-- No statement in this script is executed by analysis.\n"); foreach (var r in recommendations.Where(x => x.ProposedSql is not null && x.Risk != IndexRiskLevel.Blocked)) { b.AppendLine(); b.AppendLine($"-- {r.Severity}: {r.Summary}"); foreach (var e in r.Evidence) b.AppendLine($"-- Evidence: {e.Evidence}\n-- Limitation: {e.Limitation}"); if (r.ProposedSql!.StartsWith("DROP", StringComparison.OrdinalIgnoreCase)) b.AppendLine("-- WARNING: destructive removal is excluded from automatic execution; verify dependencies first."); b.AppendLine(r.ProposedSql); } return b.ToString(); }
    private static bool PrefixEqual(IndexMetadata small, IndexMetadata large) => small.Keys.Select(x => Normalize(x.Expression)).SequenceEqual(large.Keys.Take(small.Keys.Count).Select(x => Normalize(x.Expression)), StringComparer.OrdinalIgnoreCase) && small.IsUnique == large.IsUnique;
    private static string Normalize(string value) => string.Join(' ', value.Replace("\r", " ").Replace("\n", " ").Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries));
    private static string Qualified(IndexMetadata i) => PostgreSqlIdentifierQuoter.Qualified(i.SchemaName, i.IndexName);
}
public sealed class IndexSnapshotHistory(int maximumSnapshots = 20)
{ private readonly LinkedList<IndexAnalysisSnapshot> _items = new(); public IReadOnlyList<IndexAnalysisSnapshot> Snapshots => _items.ToArray(); public void Add(IndexAnalysisSnapshot value) { _items.AddLast(value); while (_items.Count > Math.Max(1, maximumSnapshots)) _items.RemoveFirst(); } public void Clear() => _items.Clear(); }
